def max_window_sum(nums, k=7):
    if not 1 <= k <= len(nums):
        raise ValueError("k must satisfy 1 <= k <= len(nums)")
    total = sum(nums[:k])
    best = total
    for i in range(k, len(nums)):
        total += nums[i] - nums[i - k]
        if total > best:
            best = total
    return best
```

```python
def retry_call(fn, attempts, sleep):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    for i in range(attempts):
        try:
            return fn()
        except Exception:
            if i == attempts - 1:
                raise
            sleep(0)
```

```python
def retry_call(fn, attempts, sleep):
    delay = 1
    last_exc = None

    for i in range(attempts):
        try:
            return fn()
        except Exception as exc:
            last_exc = exc
            if i < attempts - 1:
                sleep(delay)
                delay *= 2

    raise last_exc
```

