```python
def unique_usernames(names):
    seen = set()
    unique = []
    for name in names:
        if name not in seen:
            seen.add(name)
            unique.append(name)
    return unique
```

```python
def unique_usernames(names):
    """Remove duplicate usernames while preserving first-seen order."""
    seen, out = set(), []
    for name in names:
        if name not in seen:
            seen.add(name)
            out.append(name)
    return out
```

```python
def unique_usernames(names):
    """Remove duplicate usernames while preserving first occurrence order."""
    seen, out = set(), []
    for name in names:
        if name not in seen:
            seen.add(name)
            out.append(name)
    return out
```

